import copy


def expand_grid(left, right, scores):
    if not isinstance(left, list) or not isinstance(right, list) or not isinstance(scores, list):
        raise TypeError("arguments must be lists")
    if len(scores) != len(left):
        raise ValueError("wrong row count")
    if any(not isinstance(row, list) or len(row) != len(right) for row in scores):
        raise ValueError("wrong column count")
    left_values = []
    right_values = []
    score_values = []
    for i, left_item in enumerate(left):
        for j, right_item in enumerate(right):
            left_values.append(copy.deepcopy(left_item))
            right_values.append(copy.deepcopy(right_item))
            score_values.append(copy.deepcopy(scores[j][i]))
    return left_values, right_values, score_values

